/* From Uiverse.io by bandirevanth - Tags: switch */
/* Switch starts here */
.__UIV_SCOPE__ .rocker {
  display: inline-block;
  position: relative;
  /*
  SIZE OF SWITCH
  ==============
  All sizes are in em - therefore
  changing the font-size here
  will change the size of the switch.
  See .rocker-small below as example.
  */
  font-size: 2em;
  font-weight: bold;
  text-align: center;
  text-transform: uppercase;
  color: #888;
  width: 7em;
  height: 4em;
  overflow: hidden;
  border-bottom: 0.5em solid #eee;
}

.__UIV_SCOPE__ .rocker-small {
  font-size: 0.75em;
 /* Sizes the switch */
  margin: 1em;
}

.__UIV_SCOPE__ .rocker::before {
  content: "";
  position: absolute;
  top: 0.5em;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #999;
  border: 0.5em solid #eee;
  border-bottom: 0;
}

.__UIV_SCOPE__ .rocker input {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .switch-left,
.__UIV_SCOPE__ .switch-right {
  cursor: pointer;
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 2.5em;
  width: 3em;
  transition: 0.2s;
  user-select: none;
}

.__UIV_SCOPE__ .switch-left {
  height: 2.4em;
  width: 2.75em;
  left: 0.85em;
  bottom: 0.4em;
  background-color: #ddd;
  transform: rotate(15deg) skewX(15deg);
}

.__UIV_SCOPE__ .switch-right {
  right: 0.5em;
  bottom: 0;
  background-color: #bd5757;
  color: #fff;
}

.__UIV_SCOPE__ .switch-left::before,
.__UIV_SCOPE__ .switch-right::before {
  content: "";
  position: absolute;
  width: 0.4em;
  height: 2.45em;
  bottom: -0.45em;
  background-color: #ccc;
  transform: skewY(-65deg);
}

.__UIV_SCOPE__ .switch-left::before {
  left: -0.4em;
}

.__UIV_SCOPE__ .switch-right::before {
  right: -0.375em;
  background-color: transparent;
  transform: skewY(65deg);
}

.__UIV_SCOPE__ input:checked + .switch-left {
  background-color: #0084d0;
  color: #fff;
  bottom: 0px;
  left: 0.5em;
  height: 2.5em;
  width: 3em;
  transform: rotate(0deg) skewX(0deg);
}

.__UIV_SCOPE__ input:checked + .switch-left::before {
  background-color: transparent;
  width: 3.0833em;
}

.__UIV_SCOPE__ input:checked + .switch-left + .switch-right {
  background-color: #ddd;
  color: #888;
  bottom: 0.4em;
  right: 0.8em;
  height: 2.4em;
  width: 2.75em;
  transform: rotate(-15deg) skewX(-15deg);
}

.__UIV_SCOPE__ input:checked + .switch-left + .switch-right::before {
  background-color: #ccc;
}

/* Keyboard Users */
.__UIV_SCOPE__ input:focus + .switch-left {
  color: #333;
}

.__UIV_SCOPE__ input:checked:focus + .switch-left {
  color: #fff;
}

.__UIV_SCOPE__ input:focus + .switch-left + .switch-right {
  color: #fff;
}

.__UIV_SCOPE__ input:checked:focus + .switch-left + .switch-right {
  color: #333;
}
